const ORDEM_CARGO = ["GOVERNADOR","SENADOR","DEPUTADO FEDERAL","DEPUTADO ESTADUAL","DEPUTADO DISTRITAL","PREFEITO","VEREADOR"];
const ELEITO = new Set(["ELEITO","ELEITO POR QP","ELEITO POR MÉDIA"]);

const COR = {
  "MDB":"#2F8F5B","PP":"#79AEDB","PSD":"#E5C33A","PL":"#24304F","PSB":"#E8743B","UNIÃO":"#1C9C97",
  "REPUBLICANOS":"#6A4C93","PRB":"#8E73B5","PT":"#C8323C","PSDB":"#3D7BD9","PDT":"#9C2A5A","PODE":"#8BC34A",
  "DEM":"#7E9C3C","PTB":"#B5651D","AVANTE":"#F48FB1","SOLIDARIEDADE":"#F7B267","PV":"#A3D977",
  "PC do B":"#8E1B1B","PSL":"#D98E04","PROS":"#E6A0C4","PSC":"#4E7A8C","PRD":"#5D6D7E","PATRIOTA":"#2E4A3B",
  "CIDADANIA":"#C27CB0","PPS":"#C27CB0","PRTB":"#7A5C3E","PR":"#34495E","PMN":"#B0A08A","REDE":"#2AA876",
  "AGIR":"#A3876A","DC":"#6F8FAF","PRP":"#9E9E5B","PTC":"#A3876A","PHS":"#8C7AA9","PSOL":"#B39DDB",
  "NOVO":"#F07F2A","PMB":"#D96BA0","MOBILIZA":"#B0A08A","PCO":"#7B2D26","PSTU":"#A33B3B","UP":"#5A2A2A","PCB":"#912F2F"
};
const corP = sg => COR[sg] || "#8A8F98";

const fmt = new Intl.NumberFormat("pt-BR");
const brl = v => v == null ? "–" : "R$ " + new Intl.NumberFormat("pt-BR",{maximumFractionDigits: Math.abs(v)>=1000?0:2, minimumFractionDigits: Math.abs(v)>=1000?0:2}).format(v);
const brlc = v => { if (v == null) return "–"; const a=Math.abs(v);
  if (a>=1e6) return "R$ "+(v/1e6).toLocaleString("pt-BR",{maximumFractionDigits:1})+" mi";
  if (a>=1e3) return "R$ "+(v/1e3).toLocaleString("pt-BR",{maximumFractionDigits:0})+" mil";
  return "R$ "+fmt.format(Math.round(v)); };
const titulo = s => s ? String(s).toLowerCase().replace(/(^|[\s\-\/(])(\p{L})/gu,(m,a,b)=>a+b.toUpperCase()).replace(/\b(Da|De|Do|Das|Dos|E)\b/g, m=>m.toLowerCase()) : "";
const cargoNome = s => titulo(s).replace(/^Deputado /,"Deputado ").replace("Deputado Federal","Deputado federal").replace("Deputado Estadual","Deputado estadual").replace("Deputado Distrital","Deputado distrital");
const norm = s => String(s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase();
const esc = s => String(s ?? "").replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const ordemCargo = c => { const i = ORDEM_CARGO.indexOf(c); return i<0?99:i; };


// A apresentação conserva o markup, a folha de estilos, o mapa e as interações originais.
// Os dados são consultados por uma API local que mantém o token do MotherDuck no servidor.
let api;
const request = async (path) => {
  const response = await fetch(path);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || "Não foi possível consultar MotherDuck.");
  return data;
};
const painelCache = new Map();
const carregarPainel = (uf, ano) => {
  const key = `${uf}:${ano}`;
  if (!painelCache.has(key)) painelCache.set(key, request(`/api/dashboard?uf=${encodeURIComponent(uf)}&year=${ano}`));
  return painelCache.get(key);
};
api = {
  async partidos(uf, ano) {
    return (await carregarPainel(uf, ano)).parties;
  },
  async gasto(uf, ano) {
    return (await carregarPainel(uf, ano)).spending;
  },
  async buscar(uf, termo) {
    const d = await request(`/api/search?uf=${encodeURIComponent(uf)}&q=${encodeURIComponent(termo)}`);
    return {
      municipios: d.municipalities.map(m => ({ cd: m.id, nome: m.nome })),
      candidatos: d.candidates.map(c => ({
        id: c.id, nome: c.nome, urna: c.urna,
        anos: String(c.anos || "").split(", ").filter(Boolean).map(Number),
        cargos: String(c.cargos || "").split("|#|").filter(Boolean),
      })),
    };
  },
  async historico(id) {
    const d = await request(`/api/candidate/${id}`);
    const parse = (v) => typeof v === "string" ? JSON.parse(v || "[]") : (v || []);
    return {
      id, nome: d.nm_candidato, nascimento: d.dt_nascimento, instrucao: d.ds_grau_instrucao,
      genero: d.ds_genero, cor_raca: d.ds_cor_raca,
      candidaturas: d.candidacies.map(c => ({
        ...c, receitas: parse(c.receitas), despesas: parse(c.despesas), bens: parse(c.bens),
      })),
    };
  },
  async municipio(cd) {
    const d = await request(`/api/municipality/${cd}`);
    return {
      cd: d.id, nome: d.nome, uf: d.uf, ibge: d.ibge,
      comparecimento: d.attendance.map(c => ({ ano: c.ano_eleicao, turno: c.nr_turno, aptos: c.qt_aptos, comparecimento: c.qt_comparecimento, abstencao: c.qt_abstencao })),
      eleitorado: d.electorate.map(e => ({ ano: e.ano_eleicao, faixa: e.ds_faixa_etaria, qt: e.qt_eleitores })),
      mais_votados: d.topCandidates.map(c => ({ ano: c.ano_eleicao, cargo: c.cd_cargo, id: c.id_pessoa_projeto, nome: c.nm_urna_candidato, partido: c.sg_partido, votos: c.qt_votos_nominais })),
      votacao_partido: d.parties.map(p => ({ ano: p.ano_eleicao, cargo: p.cd_cargo, partido: p.sg_partido, nominais: p.qt_votos_nominais, legenda: p.qt_votos_legenda })),
      candidaturas_locais: d.localCandidacies.map(c => ({ ano: c.ano_eleicao, cargo: c.cargo, id: c.id_pessoa_projeto, nome: c.nm_urna_candidato || c.nm_candidato, partido: c.sg_partido, situacao: c.ds_sit_tot_turno, votos: c.qt_votos_nominais })),
    };
  },
  origem: "Dados ao vivo do MotherDuck · BDR-TSE",
};

/* ===================== Geometria ===================== */
const geoTodos = topojson.feature(TOPO, TOPO.objects[Object.keys(TOPO.objects)[0]]);
const GEO = Object.fromEntries(geoTodos.features.filter(f=>UFS.includes(f.properties.sigla)).map(f=>[f.properties.sigla, f]));
const W = 600, H = 520;

document.getElementById("estados").innerHTML = UFS.map(uf => {
  const p = d3.geoPath(d3.geoMercator().fitExtent([[1,1],[33,29]], GEO[uf]));
  return `<a href="#/${uf}" data-uf="${uf}"><svg viewBox="0 0 34 30" aria-hidden="true"><path d="${p(GEO[uf])}"/></svg>${uf}</a>`;
}).join("");

/* Cortes verticais cuja área dentro do estado é proporcional à parcela de cada partido */
const cacheArea = {};
function cortesPorArea(uf, pathStr){
  if (!cacheArea[uf]){
    const cv = document.createElement("canvas"); cv.width = W; cv.height = H;
    const cx = cv.getContext("2d"); cx.fill(new Path2D(pathStr));
    const px = cx.getImageData(0,0,W,H).data, col = new Float64Array(W);
    for (let y=0; y<H; y++) for (let x=0; x<W; x++) col[x] += px[(y*W+x)*4+3]/255;
    const acc = new Float64Array(W+1); for (let x=0; x<W; x++) acc[x+1] = acc[x]+col[x];
    cacheArea[uf] = acc;
  }
  const acc = cacheArea[uf], total = acc[W];
  return frac => { const alvo = frac*total; let lo=0, hi=W;
    while (hi-lo>1){ const m=(lo+hi)>>1; if (acc[m] < alvo) lo=m; else hi=m; }
    const a = acc[lo], b = acc[hi]; return lo + (b>a ? (alvo-a)/(b-a) : 0); };
}

/* ===================== Estado da página ===================== */
let UF = "SP", ANO = 2022, CARGO = "TODOS", LINHAS = [];
const svg = d3.select("#forma"), tip = document.getElementById("tip");

function anosDisponiveis(uf){ return uf === "DF" ? [2018, 2022] : ANOS; }

async function abrirEstado(uf){
  UF = uf; CARGO = "TODOS";
  if (!anosDisponiveis(uf).includes(ANO)) ANO = 2022;
  document.querySelectorAll("#estados a").forEach(a => a.setAttribute("aria-current", a.dataset.uf===uf ? "page" : "false"));
  document.getElementById("uf-nome").textContent = GEO[uf].properties.nome;
  document.title = GEO[uf].properties.nome + ": eleitos por partido";
  document.getElementById("busca").value = ""; fecharResultados();
  document.getElementById("busca").placeholder = "Buscar município ou candidato"; document.getElementById("busca").setAttribute("aria-label", `Buscar município ou candidato em ${GEO[uf].properties.nome}`);
  montarAnos(); await carregarAno();
}

function montarAnos(){
  const el = document.getElementById("anos"), disp = anosDisponiveis(UF);
  el.innerHTML = ANOS.map(a => `<button class="ano-btn" data-ano="${a}" aria-pressed="${a===ANO}" ${disp.includes(a)?"":"disabled title=\"O DF não tem eleições municipais\""}>${a}</button>`).join("");
  el.querySelectorAll("button").forEach(b => b.onclick = () => { ANO = +b.dataset.ano; CARGO = "TODOS"; montarAnos(); carregarAno(); });
}

async function carregarAno(){
  const [linhas, gasto] = await Promise.all([api.partidos(UF, ANO), api.gasto(UF, ANO)]);
  LINHAS = linhas;
  montarCargos(); desenharForma(true); montarQuartis(gasto);
}

function montarCargos(){
  const cargos = [...new Set(LINHAS.map(r=>r.ds_cargo))].sort((a,b)=>ordemCargo(a)-ordemCargo(b));
  const el = document.getElementById("cargos");
  el.innerHTML = [["TODOS","Todos os cargos"], ...cargos.map(c=>[c, cargoNome(c)])]
    .map(([v,t]) => `<button data-c="${v}" aria-pressed="${CARGO===v}">${t}</button>`).join("");
  el.querySelectorAll("button").forEach(b => b.onclick = () => { CARGO = b.dataset.c; montarCargos(); desenharForma(true); });
}

function agregados(){
  const m = new Map();
  for (const r of LINHAS){ if (CARGO!=="TODOS" && r.ds_cargo!==CARGO) continue;
    const k = r.sg_partido, o = m.get(k) || {sg:k, nm:r.nm_partido, qt:0, cargos:{}};
    o.qt += +r.qt_eleitos; o.cargos[r.ds_cargo] = (o.cargos[r.ds_cargo]||0) + +r.qt_eleitos; if (!o.nm) o.nm = r.nm_partido; m.set(k,o); }
  return [...m.values()].sort((a,b)=>b.qt-a.qt || a.sg.localeCompare(b.sg));
}

function desenharForma(animar){
  const f = GEO[UF];
  const proj = d3.geoMercator().fitExtent([[12,12],[W-12,H-12]], f), path = d3.geoPath(proj), d = path(f);
  const partes = agregados(), total = d3.sum(partes, p=>p.qt);
  const cargosTxt = [...new Set(LINHAS.map(r=>r.ds_cargo))].sort((a,b)=>ordemCargo(a)-ordemCargo(b)).map(c=>cargoNome(c).toLowerCase());
  const totAno = d3.sum(LINHAS, r=>+r.qt_eleitos);
  document.getElementById("resumo").textContent = totAno
    ? `${fmt.format(totAno)} eleitos na base em ${ANO}, de ${new Set(LINHAS.map(r=>r.sg_partido)).size} partidos, para ${cargosTxt.join(", ").replace(/, ([^,]*)$/," e $1")}.`
    : `Nenhum eleito na base para ${ANO}.`;

  svg.selectAll("*").remove();
  const defs = svg.append("defs");
  defs.append("clipPath").attr("id","clip-uf").append("path").attr("d", d);
  const vazio = document.getElementById("forma-vazia");

  if (!total){
    svg.append("path").attr("d", d).style("fill", "var(--vazio)");
    vazio.hidden = false; vazio.textContent = UF==="DF" && (ANO===2020||ANO===2024) ? "O Distrito Federal não tem eleições municipais." : "Sem eleitos na base para este filtro.";
    montarLegenda([], 0); return;
  }
  vazio.hidden = true;
  const corte = cortesPorArea(UF, d);
  const [[x0,y0],[x1,y1]] = path.bounds(f);
  let acum = 0;
  const faixas = partes.map(p => { const a = corte(acum/total); acum += p.qt; const b = corte(acum/total); return {...p, a, b}; });

  const g = svg.append("g").attr("clip-path","url(#clip-uf)");
  g.selectAll("rect").data(faixas, p=>p.sg).join("rect")
    .attr("class","faixa").attr("data-sg", p=>p.sg)
    .attr("y", y0-2).attr("height", y1-y0+4).attr("fill", p=>corP(p.sg))
    .attr("x", p => animar ? x0 : p.a).attr("width", p => animar ? 0 : Math.max(0,p.b-p.a+0.6))
    .call(s => { if (!animar || matchMedia("(prefers-reduced-motion: reduce)").matches) return s.attr("x",p=>p.a).attr("width",p=>Math.max(0,p.b-p.a+0.6));
      s.transition().duration(700).delay((p,i)=>i*35).ease(d3.easeCubicOut).attr("x",p=>p.a).attr("width",p=>Math.max(0,p.b-p.a+0.6)); })
    .on("mousemove", (ev,p) => mostrarTip(ev, p, total))
    .on("mouseleave", () => { tip.classList.remove("on"); realcar(null); });
  svg.append("path").attr("class","contorno").attr("d", d);
  montarLegenda(partes, total);
}

function mostrarTip(ev, p, total){
  realcar(p.sg);
  const cargos = Object.entries(p.cargos).sort((a,b)=>ordemCargo(a[0])-ordemCargo(b[0])).map(([c,q])=>`${cargoNome(c)}: ${q}`).join("<br>");
  tip.innerHTML = `<b>${esc(p.sg)}${p.nm && p.nm!==p.sg ? ", " + esc(titulo(p.nm)) : ""}</b>${p.qt} ${p.qt===1?"eleito":"eleitos"} (${(p.qt/total*100).toLocaleString("pt-BR",{maximumFractionDigits:1})}%)<br>${cargos}`;
  const box = document.querySelector(".forma-box").getBoundingClientRect();
  let x = ev.clientX - box.left + 14; if (x > box.width - 250) x -= 270;
  tip.style.left = x+"px"; tip.style.top = (ev.clientY - box.top + 14)+"px"; tip.classList.add("on");
}
function realcar(sg){
  document.getElementById("forma").classList.toggle("foco", !!sg);
  svg.selectAll(".faixa").classed("on", p => p.sg === sg);
}

function montarLegenda(partes, total){
  const max = d3.max(partes, p=>p.qt) || 1;
  const ol = document.getElementById("legenda");
  ol.innerHTML = partes.map(p => `<li data-sg="${esc(p.sg)}" title="${esc(titulo(p.nm||p.sg))}">
      <i class="sw" style="background:${corP(p.sg)}"></i><span class="sg">${esc(p.sg)}</span>
      <i class="bar" style="width:${(p.qt/max*100).toFixed(1)}%;background:${corP(p.sg)}"></i>
      <span class="q num">${p.qt} <small>${Math.round(p.qt/total*100)}%</small></span></li>`).join("");
  ol.querySelectorAll("li").forEach(li => { li.onmouseenter = () => realcar(li.dataset.sg); li.onmouseleave = () => realcar(null); });
}

function montarQuartis(linhas){
  const el = document.getElementById("quartis");
  const porCargo = d3.group(linhas, r=>r.ds_cargo);
  const cargos = [...porCargo.keys()].sort((a,b)=>ordemCargo(a)-ordemCargo(b));
  if (!cargos.length){ el.innerHTML = `<p class="nota">Sem candidatos com prestação de contas na base para ${ANO}.</p>`; return; }
  el.innerHTML = cargos.map(c => {
    const rows = porCargo.get(c);
    const n = d3.sum(rows, q=>+q.qtd_candidatos_na_faixa), el_ = d3.sum(rows, q=>+q.qtd_eleitos);
    // as faixas têm o mesmo tamanho em reais; o limite de cada uma vem da maior faixa do cargo
    const topo = d3.max(rows, q=>+q.limite_superior_faixa) || 0;
    const faixas = [1,2,3,4].map(k => rows.find(q=>+q.faixa_financeira===k) || { faixa_financeira:k, vazia:true, limite_superior_faixa: topo*k/4 });
    // média geral de eleitos e não eleitos, recomposta a partir das médias de cada faixa
    const pond = (campo, qtd) => { const v = rows.filter(q=>q[campo]!=null); const w = d3.sum(v, qtd); return w ? d3.sum(v, q=>+q[campo]*qtd(q))/w : null; };
    const mEl = pond("media_gasto_eleitos", q=>+q.qtd_eleitos), mNao = pond("media_gasto_nao_eleitos", q=>+q.qtd_candidatos_na_faixa - q.qtd_eleitos);
    return `<div class="qc"><h3>${cargoNome(c)}</h3><p class="nota" style="margin:-.4rem 0 0">${n} ${n===1?"candidato":"candidatos"}, ${el_} ${el_===1?"eleito":"eleitos"}</p>
      <div class="barras">${faixas.map(q => q.vazia
        ? `<div class="b vazia" title="Nenhum candidato nesta faixa"><span>–</span></div>`
        : `<div class="b" style="height:${Math.max(2,+q.taxa_sucesso_pct)}%" title="${q.qtd_eleitos} de ${q.qtd_candidatos_na_faixa} eleitos; gastos de ${brl(+q.piso_faixa)} a ${brl(+q.teto_faixa)}"><span>${(+q.taxa_sucesso_pct).toLocaleString("pt-BR",{maximumFractionDigits:0})}%</span></div>`).join("")}</div>
      <div class="eixo num">${faixas.map(q=>`<span>até<br>${brlc(+q.limite_superior_faixa)}<br><em>${q.vazia ? "ninguém" : q.qtd_candidatos_na_faixa + (+q.qtd_candidatos_na_faixa===1?" cand.":" cand.")}</em></span>`).join("")}</div>
      <p class="med">Gasto médio: eleitos <b>${brlc(mEl)}</b>, não eleitos <b>${brlc(mNao)}</b></p></div>`;
  }).join("");
}

/* ===================== Busca ===================== */
const inp = document.getElementById("busca"), res = document.getElementById("resultados");
let tBusca = null, selIdx = -1;
inp.addEventListener("input", () => { clearTimeout(tBusca); tBusca = setTimeout(buscar, 180); });
inp.addEventListener("keydown", ev => {
  const itens = [...res.querySelectorAll("button")]; if (res.hidden || !itens.length) return;
  if (ev.key==="ArrowDown"){ selIdx = Math.min(itens.length-1, selIdx+1); ev.preventDefault(); }
  else if (ev.key==="ArrowUp"){ selIdx = Math.max(0, selIdx-1); ev.preventDefault(); }
  else if (ev.key==="Enter"){ (itens[selIdx] || itens[0]).click(); ev.preventDefault(); return; }
  else if (ev.key==="Escape"){ fecharResultados(); return; } else return;
  itens.forEach((b,i)=>b.classList.toggle("sel", i===selIdx)); itens[selIdx]?.scrollIntoView({block:"nearest"});
});
document.addEventListener("click", ev => { if (!ev.target.closest(".busca")) fecharResultados(); });
function fecharResultados(){ res.hidden = true; selIdx = -1; }

async function buscar(){
  const termo = inp.value; if (termo.trim().length < 2){ fecharResultados(); return; }
  const r = await api.buscar(UF, termo); selIdx = -1;
  let h = "";
  if (r.municipios?.length) h += `<h3>Municípios</h3>` + r.municipios.map(m=>`<button data-tipo="m" data-id="${m.cd}"><span class="r-nm">${esc(titulo(m.nome))}</span></button>`).join("");
  if (r.candidatos?.length) h += `<h3>Candidatos</h3>` + r.candidatos.map(c=>`<button data-tipo="c" data-id="${c.id}"><span class="r-nm">${esc(titulo(c.urna||c.nome))}</span>
      <span class="r-meta">${esc(titulo(c.nome))}, ${[...c.cargos].sort((a,b)=>ordemCargo(a)-ordemCargo(b)).map(cargoNome).join(", ")} (${c.anos.join(", ")})</span></button>`).join("");
  res.innerHTML = h || `<div class="vazio">Nada encontrado em ${GEO[UF].properties.nome} para “${esc(termo)}”.</div>`;
  res.hidden = false;
  res.querySelectorAll("button").forEach(b => b.onclick = () => { fecharResultados(); b.dataset.tipo==="m" ? abrirMunicipio(b.dataset.id) : abrirCandidato(+b.dataset.id); });
}

/* ===================== Gaveta ===================== */
const gaveta = document.getElementById("gaveta"), scrim = document.getElementById("scrim"), corpo = document.getElementById("g-corpo");
let ultimoFoco = null;
function abrirGaveta(html){
  if (!gaveta.classList.contains("on")) ultimoFoco = document.activeElement;
  corpo.innerHTML = html; gaveta.scrollTop = 0;
  gaveta.classList.add("on"); scrim.classList.add("on"); gaveta.focus();
  corpo.querySelectorAll("[data-cand]").forEach(b => b.onclick = () => abrirCandidato(+b.dataset.cand));
  corpo.querySelectorAll("[data-mun]").forEach(b => b.onclick = () => abrirMunicipio(b.dataset.mun));
}
function fecharGaveta(){ gaveta.classList.remove("on"); scrim.classList.remove("on"); ultimoFoco?.focus?.(); }
document.getElementById("fechar").onclick = fecharGaveta; scrim.onclick = fecharGaveta;
document.addEventListener("keydown", ev => { if (ev.key==="Escape" && gaveta.classList.contains("on")) fecharGaveta(); });

const idade = (nasc, ano) => { if (!nasc) return null; const [y,m,d] = nasc.split("-").map(Number); const ref = new Date(ano, 9, 1); let i = ref.getFullYear()-y; if (ref < new Date(ref.getFullYear(), m-1, d)) i--; return i; };
const ehEleito = s => ELEITO.has(s);
const sitTxt = s => s ? titulo(s).replace("Por Qp","por QP").replace("Por Média","por média").replace("Não Eleito","Não eleito") : "Sem resultado";

async function abrirCandidato(id){
  const h = await api.historico(id);
  if (!h){ abrirGaveta(`<h2>Candidato não encontrado</h2><p class="sub">Não há registro para este identificador na base.</p>`); return; }
  const cs = h.candidaturas.filter(c => c.cargo).sort((a,b)=>a.ano_eleicao-b.ano_eleicao || ordemCargo(a.cargo)-ordemCargo(b.cargo));
  const eleicoes = cs.filter(c=>ehEleito(c.situacao)).length;
  const urna = [...new Set(cs.map(c=>c.nm_urna_candidato))].map(titulo).join(" / ");
  const ultimaIdade = cs.length ? idade(h.nascimento, cs[cs.length-1].ano_eleicao) : null;

  const item = c => {
    const el = ehEleito(c.situacao);
    const local = c.nm_municipio ? `${titulo(c.nm_municipio)} (${c.uf})` : c.uf;
    const rp = +c.receitas_publicas||0, rv = +c.receitas_privadas||0, rt = +c.total_receitas||0;
    const custoVoto = c.votos > 0 && c.total_despesas > 0 ? c.total_despesas / c.votos : null;
    const receitas = c.receitas.length ? `<details><summary>Receitas por fonte</summary><div class="tabw"><table class="tab"><thead><tr><th>Fonte</th><th>Origem</th><th class="v">Lançamentos</th><th class="v">Valor</th></tr></thead><tbody>
      ${c.receitas.map(r=>`<tr><td>${esc(titulo(r.fonte))}</td><td>${esc(titulo(r.origem))}</td><td class="v">${r.qtd}</td><td class="v">${brl(r.valor)}</td></tr>`).join("")}</tbody></table></div></details>` : "";
    const despesas = c.despesas.length ? `<details><summary>Maiores despesas (${Math.min(c.despesas.length, c.qt_despesas)} de ${fmt.format(c.qt_despesas)})</summary><div class="tabw"><table class="tab"><tbody>
      ${c.despesas.map(d=>`<tr><td>${esc(d.despesa ? d.despesa.toLowerCase().replace(/^./,x=>x.toUpperCase()) : "Sem descrição")}</td><td class="v">${brl(d.valor)}</td></tr>`).join("")}</tbody></table></div></details>` : "";
    const bens = c.bens.length ? `<details><summary>Bens declarados (${c.bens.length})</summary><div class="tabw"><table class="tab"><tbody>
      ${c.bens.map(b=>`<tr><td>${esc(b.tipo)}${b.descricao ? `<br><span style="color:var(--ink-3)">${esc(b.descricao.toLowerCase())}</span>` : ""}</td><td class="v">${brl(b.valor)}</td></tr>`).join("")}</tbody></table></div></details>` : "";
    return `<li class="${el?"el":""}">
      <div class="lt-ano">${c.ano_eleicao}</div>
      <div class="lt-cargo">${cargoNome(c.cargo)}, ${esc(local)} <span class="chip" style="background:${corP(c.partido)}">${esc(c.partido)}</span><span class="sit ${el?"el":""}">${sitTxt(c.situacao)}</span></div>
      <div class="grade">
        <div><small>Votos (1º turno)</small><b class="num">${c.votos!=null ? fmt.format(c.votos) : "–"}</b></div>
        <div><small>Receitas</small><b class="num">${brlc(rt)}</b>${rt ? `<div class="split"><i style="width:${rp/rt*100}%;background:var(--ink)"></i><i style="width:${rv/rt*100}%;background:var(--ink-3)"></i></div><div class="legenda-split">${Math.round(rp/rt*100)}% público, ${Math.round(rv/rt*100)}% privado</div>` : ""}</div>
        <div><small>Despesas pagas</small><b class="num">${brlc(+c.total_despesas)}</b>${custoVoto ? `<div class="legenda-split">${brl(custoVoto)} por voto</div>` : ""}</div>
        <div><small>Patrimônio declarado</small><b class="num">${brlc(+c.patrimonio_declarado)}</b></div>
      </div>
      ${receitas}${despesas}${bens}
    </li>`;
  };

  // evolução do patrimônio
  const pat = cs.filter(c=>+c.patrimonio_declarado>0);
  const anosUnicos = [...new Set(cs.map(c=>c.ano_eleicao))];
  let evol = "";
  if (anosUnicos.length > 1){
    const porAno = d3.rollups(cs, v=>d3.max(v, c=>+c.patrimonio_declarado||0), c=>c.ano_eleicao);
    const mx = d3.max(porAno, d=>d[1]) || 1;
    evol = `<h3>Patrimônio declarado ao longo das eleições</h3>` + porAno.map(([a,v]) => `<div class="hb"><span>${a}</span><i class="t" style="width:${v/mx*100}%"></i><span class="v">${brlc(v)}</span></div>`).join("");
  }

  abrirGaveta(`
    <h2 id="g-titulo">${esc(titulo(h.nome))}</h2>
    <p class="sub">${urna ? "Na urna: " + esc(urna) : ""}</p>
    <ul class="fatos">
      <li><b>${cs.length}</b> ${cs.length===1?"candidatura":"candidaturas"} na base</li>
      <li><b>${eleicoes}</b> ${eleicoes===1?"vez eleito":"vezes eleito"}</li>
      ${ultimaIdade!=null ? `<li><b>${ultimaIdade}</b> anos em ${cs[cs.length-1].ano_eleicao}</li>` : ""}
      ${h.genero ? `<li>${esc(titulo(h.genero))}</li>` : ""}${h.cor_raca ? `<li>${esc(titulo(h.cor_raca))}</li>` : ""}
      ${h.instrucao ? `<li>${esc(titulo(h.instrucao).replace(/^./,x=>x.toUpperCase()).replace(/\b(Completo|Incompleto|Fundamental|Médio|Superior)\b/g,m=>m.toLowerCase()).replace(/^./,x=>x.toUpperCase()))}</li>` : ""}
    </ul>
    ${evol}
    <h3>Trajetória</h3>
    <ol class="linha-tempo">${cs.map(item).join("")}</ol>
    <p class="aviso-mini">A trajetória reúne as candidaturas ligadas ao mesmo identificador de pessoa do projeto. Receitas de fundo especial e fundo partidário contam como públicas; outros recursos, como privados.</p>`);
}

async function abrirMunicipio(cd){
  const m = await api.municipio(cd);
  if (!m){ abrirGaveta(`<h2>Município não encontrado</h2>`); return; }
  let h = `<h2 id="g-titulo">${esc(titulo(m.nome))}</h2><p class="sub">${esc(m.uf)}, código TSE ${esc(m.cd)}${m.ibge ? `, código IBGE ${esc(m.ibge)}` : ""}</p>`;
  const faltam = [];

  // comparecimento
  if (m.comparecimento.length){
    h += `<h3>Comparecimento</h3><div class="tabw"><table class="tab"><thead><tr><th>Eleição</th><th class="v">Aptos</th><th class="v">Compareceram</th><th class="v">Abstenção</th></tr></thead><tbody>
      ${m.comparecimento.map(c=>`<tr><td>${c.ano}, ${c.turno}º turno</td><td class="v">${fmt.format(c.aptos)}</td><td class="v">${fmt.format(c.comparecimento)}</td><td class="v">${(c.abstencao/c.aptos*100).toLocaleString("pt-BR",{maximumFractionDigits:1})}%</td></tr>`).join("")}</tbody></table></div>`;
  } else faltam.push("comparecimento");

  // candidaturas locais (prefeito e vereador)
  const loc = m.candidaturas_locais || [];
  if (loc.length){
    const anosL = [...new Set(loc.map(c=>c.ano))].sort();
    h += `<h3>Eleições municipais</h3>`;
    for (const a of anosL){
      const pref = loc.filter(c=>c.ano===a && c.cargo==="PREFEITO");
      const ver = loc.filter(c=>c.ano===a && c.cargo==="VEREADOR" && ehEleito(c.situacao));
      const verTot = loc.filter(c=>c.ano===a && c.cargo==="VEREADOR").length;
      const porPart = d3.rollups(ver, v=>v.length, c=>c.partido).sort((x,y)=>y[1]-x[1]);
      h += `<p style="margin:.8rem 0 .3rem;font-weight:700">${a}</p>`;
      if (pref.length) h += `<div class="tabw"><table class="tab"><thead><tr><th>Prefeito</th><th>Partido</th><th>Resultado</th><th class="v">Votos</th></tr></thead><tbody>${pref.map(c=>`<tr><td><button class="link" data-cand="${c.id}">${esc(titulo(c.nome))}</button></td><td>${esc(c.partido)}</td><td>${sitTxt(c.situacao)}</td><td class="v">${c.votos!=null?fmt.format(c.votos):"–"}</td></tr>`).join("")}</tbody></table></div>`;
      if (verTot) h += `<p class="aviso-mini">${ver.length} vereadores eleitos entre ${verTot} candidatos na base${porPart.length ? ": " + porPart.map(([p,n])=>`<span class="chip" style="background:${corP(p)}">${esc(p)} ${n}</span>`).join(" ") : ""}</p>`;
      if (ver.length) h += `<details><summary>Ver vereadores eleitos</summary><div class="tabw"><table class="tab"><tbody>${ver.map(c=>`<tr><td><button class="link" data-cand="${c.id}">${esc(titulo(c.nome))}</button></td><td>${esc(c.partido)}</td><td class="v">${c.votos!=null?fmt.format(c.votos):"–"}</td></tr>`).join("")}</tbody></table></div></details>`;
    }
  }

  // mais votados no município
  const mv = m.mais_votados || [];
  if (mv.length){
    h += `<h3>Mais votados no município (1º turno)</h3><div class="ctrl"><select id="mv-sel" aria-label="Eleição e cargo">${
      [...new Map(mv.map(r=>[`${r.ano}|${r.cargo}`, r])).values()].sort((a,b)=>b.ano-a.ano||a.cargo-b.cargo).map(r=>`<option value="${r.ano}|${r.cargo}">${r.ano}, ${CARGO_COD[r.cargo]||r.cargo}</option>`).join("")}</select></div><div id="mv-lista"></div>`;
  }

  // votação por partido
  const vp = m.votacao_partido || [];
  if (vp.length){
    h += `<h3>Votos por partido (1º turno)</h3><div class="ctrl"><select id="vp-sel" aria-label="Eleição e cargo">${
      [...new Map(vp.map(r=>[`${r.ano}|${r.cargo}`, r])).values()].sort((a,b)=>b.ano-a.ano||a.cargo-b.cargo).map(r=>`<option value="${r.ano}|${r.cargo}">${r.ano}, ${CARGO_COD[r.cargo]||r.cargo}</option>`).join("")}</select></div><div id="vp-lista"></div>`;
  } else faltam.push("votação por partido");

  // eleitorado
  const el = m.eleitorado || [];
  if (el.length){
    h += `<h3>Eleitorado por faixa etária</h3><div class="ctrl"><select id="el-sel" aria-label="Ano">${[...new Set(el.map(e=>e.ano))].sort().reverse().map(a=>`<option>${a}</option>`).join("")}</select></div><div id="el-lista"></div>`;
  } else faltam.push("perfil do eleitorado");

  if (faltam.length) h += `<p class="aviso-mini">Sem dados de ${faltam.join(", ").replace(/, ([^,]*)$/," e $1")} para este município na base.</p>`;
  abrirGaveta(h);

  const ligar = (selId, listaId, render) => { const s = document.getElementById(selId); if (!s) return; const f = () => { document.getElementById(listaId).innerHTML = render(s.value);
      document.getElementById(listaId).querySelectorAll("[data-cand]").forEach(b => b.onclick = () => abrirCandidato(+b.dataset.cand)); }; s.onchange = f; f(); };
  ligar("mv-sel","mv-lista", v => { const [a,c] = v.split("|").map(Number); const rows = mv.filter(r=>r.ano===a && r.cargo===c); const mx = d3.max(rows, r=>r.votos)||1;
    return rows.map(r=>`<div class="hb"><button class="link" data-cand="${r.id}" style="font-weight:500">${esc(titulo(r.nome))} <span style="color:var(--ink-3)">${esc(r.partido)}</span></button><i class="t" style="width:${r.votos/mx*100}%;background:${corP(r.partido)}"></i><span class="v">${fmt.format(r.votos)}</span></div>`).join(""); });
  ligar("vp-sel","vp-lista", v => { const [a,c] = v.split("|").map(Number); const rows = vp.filter(r=>r.ano===a && r.cargo===c).map(r=>({...r, t:r.nominais+r.legenda})).sort((x,y)=>y.t-x.t).slice(0,10); const mx = d3.max(rows, r=>r.t)||1;
    return rows.map(r=>`<div class="hb"><span>${esc(r.partido)}</span><i class="t" style="width:${r.t/mx*100}%;background:${corP(r.partido)}"></i><span class="v">${fmt.format(r.t)}</span></div>`).join("") + `<p class="aviso-mini">Soma de votos nominais e de legenda; 10 partidos mais votados.</p>`; });
  ligar("el-sel","el-lista", v => { const ini = s => parseInt(s,10) || 0;
    const rows = el.filter(e=>String(e.ano)===v && e.qt>0 && /\d/.test(e.faixa)).sort((x,y)=>ini(x.faixa)-ini(y.faixa)); const tot = d3.sum(rows, r=>r.qt), mx = d3.max(rows, r=>r.qt)||1;
    return rows.map(r=>`<div class="hb"><span>${esc(r.faixa)}</span><i class="t" style="width:${r.qt/mx*100}%"></i><span class="v">${(r.qt/tot*100).toLocaleString("pt-BR",{maximumFractionDigits:1})}%</span></div>`).join("") + `<p class="aviso-mini">${fmt.format(tot)} eleitores cadastrados.</p>`; });
}

/* ===================== Tema claro / escuro ===================== */
const raiz = document.documentElement, botaoTema = document.getElementById("tema");
const temaAtual = () => raiz.dataset.theme || (matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light");
function rotularTema(){
  const escuro = temaAtual() === "dark";
  // o botão mostra o modo para o qual ele leva
  document.getElementById("tema-txt").textContent = escuro ? "Modo claro" : "Modo escuro";
  botaoTema.classList.toggle("escuro", !escuro);
  botaoTema.setAttribute("aria-label", escuro ? "Mudar para o modo claro" : "Mudar para o modo escuro");
}
botaoTema.onclick = () => {
  const novo = temaAtual() === "dark" ? "light" : "dark";
  raiz.dataset.theme = novo;
  try { localStorage.setItem("tema", novo); } catch(e) {}
  rotularTema();
};
matchMedia("(prefers-color-scheme: dark)").addEventListener("change", rotularTema);
rotularTema();

/* ===================== Rotas e início ===================== */
function rota(){ const uf = (location.hash.match(/#\/([A-Z]{2})/)||[])[1]; abrirEstado(UFS.includes(uf) ? uf : "SP"); }
window.addEventListener("hashchange", rota);
(async () => {
  const origem = document.getElementById("origem");
  try {
    await request("/api/health");
    origem.textContent = api.origem;
    rota();
  } catch(e){
    console.error(e);
    document.getElementById("carregando").innerHTML = `<span class="erro">${esc(e.message || "Não foi possível carregar os dados. Verifique MOTHERDUCK_TOKEN e atualize a página.")}</span>`;
    return;
  }
  document.getElementById("carregando").hidden = true;
})();
